for (const name of ['a.txt', 'd', 'nope']) {
  const [st, err] = os.stat('/data/' + name)
  const kind = err !== 0 ? 'none' : (st.mode & os.S_IFMT) === os.S_IFDIR ? 'dir' : (st.mode & os.S_IFMT) === os.S_IFREG ? 'file' : 'other'
  console.log(name, err, kind, err === 0 && kind === 'file' ? st.size : '')
}

