const fsp = require('node:fs').promises
for (const name of ['a.txt', 'd', 'nope']) {
  const p = '/data/' + name
  const there = await fsp.access(p).then(() => true, () => false)
  const st = await fsp.stat(p).catch((e) => e.code)
  console.log(name, there, typeof st === 'string' ? st : st.isFile(), typeof st === 'string' ? st : st.isDirectory())
}
console.log((await fsp.stat('/data/a.txt')).size)
